begin;

-- Password for every seeded account: demo-circulo-2026
-- Hashed here with pgcrypto so these accounts can sign in immediately after
-- `supabase db reset`, with no separate Admin API step (and no risk of that step
-- silently no-opping against a user auth.users already has, which is what an
-- `insert ... on conflict do nothing` followed by a separate password-setting
-- call would do).

select set_config('circulo.demo_password_hash', crypt('demo-circulo-2026', gen_salt('bf')), true);

-- --- auth users ---------------------------------------------------------
-- A fully-formed row, not just id + email: GoTrue needs aud/role set to
-- 'authenticated' and email_confirmed_at set, or it treats the account as
-- unconfirmed and refuses password sign-in.

on conflict (user_id) do nothing;

